```rust
fn merge_without_overwrite(legacy: &Path, dest: &Path) -> std::io::Result<MergeOutcome> {
    let mut first_skipped: Option<PathBuf> = None;
    for entry in std::fs::read_dir(legacy)? {
        let entry = entry?;
        let src = entry.path();
        let target = dest.join(entry.file_name());
        if target.exists() {
            first_skipped.get_or_insert(src);
            continue;
        }
        if entry.file_type()?.is_dir() {
            std::fs::create_dir_all(&target)?;
            let nested = merge_without_overwrite(&src, &target)?;
            if let MergeOutcome::Skipped(first) = nested {
                first_skipped.get_or_insert(first);
            } else {
                let _ = std::fs::remove_dir(&src);
            }
        } else {
            std::fs::rename(&src, &target)?;
        }
    }
    Ok(match first_skipped {
        Some(first) => MergeOutcome::Skipped(first),
        None => MergeOutcome::Emptied,
    })
}
```

