fn resolve_identity(rows: &[ProcessedAlbum], artist_dir: &str, album_dir: &str) -> Option<StagedIdentity> {
    let mut matches: Vec<&ProcessedAlbum> = rows
        .iter()
        .filter(|row| {
            sanitize_component(&row.artist).eq_ignore_ascii_case(artist_dir)
                && sanitize_component(&row.album).eq_ignore_ascii_case(album_dir)
        })
        .collect();
    matches.sort_by_key(|row| row.id);
    let (last, rest) = matches.split_last()?;
    if let Some(first) = rest.first() {
        tracing::warn!(
            "Staging directory {artist_dir:?}/{album_dir:?} matches several processed albums; \
             using the newest: {:?} - {:?} (also matched {:?} - {:?}, oldest first)",
            last.artist, last.album, first.artist, first.album
        );
    }
    Some(StagedIdentity {
        artist: last.artist.clone(),
        album: last.album.clone(),
        status: last.status.clone(),
    })
}
```

