/// True when `path` can be migrated without risking a staged album: it holds a
/// file at its top level, or it holds nothing at all.
///
/// A file is positive evidence of a legacy album directory, because the current
/// layout never puts a file directly inside an artist level, only inside its
/// album directories. A directory whose children are all directories is *not*
/// evidence: a legacy multi-disc album directory (its tracks all inside `CD 01/`)
/// and an artist level whose albums are named like disc folders are the same
/// shape, and renaming the second moves a staged album a level deeper. An empty
/// directory has nothing to lose, so it is migrated as debris.
fn looks_like_a_legacy_album(path: &Path) -> bool {
    let Ok(entries) = std::fs::read_dir(path) else {
        return false;
    };
    let mut holds_a_file = false;
    let mut holds_a_directory = false;
    for entry in entries.flatten() {
        if entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false) {
            holds_a_directory = true;
        } else {
            holds_a_file = true;
        }
    }
    holds_a_file || !holds_a_directory
}

