/// True when two paths name the same existing directory. The staging layout
/// mirrors the library layout, so a staging root inside a library root makes an
/// album's staging path and its library destination the same directory; the
/// comparison is canonical, so a symlinked or `.`-containing spelling of either
/// path still matches. Only real equality triggers the guard: a staging root
/// merely nested inside a library root is a different directory, and its copy is
/// removed as usual.
fn is_the_same_dir(left: &Path, right: &Path) -> bool {
    match (std::fs::canonicalize(left), std::fs::canonicalize(right)) {
        (Ok(left), Ok(right)) => left == right,
        _ => false,
    }
}

