///
/// The staging layout mirrors the library layout, so a staging root placed inside
/// a library root makes an album's staging path and its library destination the
/// same directory. The write paths guard against copying or removing in that
/// state; this is the test they share.
fn is_inside_a_library(config: &Config, path: &Path) -> bool {
    config.library.paths.iter().any(|root| {
        let root = Path::new(root);
        !root.as_os_str().is_empty() && path.starts_with(root)
    })
}

