/// True when `path` can be migrated without risking a staged album: it holds an
/// audio file at its top level, or it holds nothing at all.
///
/// The evidence must be audio, not merely a file. A stray sidecar (`.DS_Store`,
/// `cover.jpg`, a `.part`) at the top level of an artist level whose name carries
/// the separator would otherwise be enough to rename that whole artist tree into
/// a fabricated album directory, which recovery then deletes. The stager only
/// ever writes audio at an album's top level, so audio is what tells the two
/// shapes apart.
///
/// A directory whose children are all directories is not evidence either way — a
/// legacy multi-disc album directory (tracks all inside `CD 01/`) and an artist
/// level whose albums are named like disc folders are the same shape — and an
/// empty directory has nothing to lose, so it is migrated as debris.
fn looks_like_a_legacy_album(path: &Path) -> bool {
    let Ok(entries) = std::fs::read_dir(path) else {
        return false;
    };
    let mut holds_audio = false;
    let mut holds_a_directory = false;
    for entry in entries.flatten() {
        if entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false) {
            holds_a_directory = true;
        } else if crate::organizer::parses_as_audio(&entry.path()) {
            holds_audio = true;
        }
    }
    holds_audio || !holds_a_directory
}

