/// path still matches. Only real equality triggers the guard: a staging root
/// merely nested inside a library root is a different directory, and its copy is
/// removed as usual.
fn is_the_same_dir(left: &Path, right: &Path) -> bool {
    match (std::fs::canonicalize(left), std::fs::canonicalize(right)) {
        (Ok(left), Ok(right)) => left == right,
        _ => false,
    }
}

/// Remove a directory once it holds nothing. `remove_dir` refuses a non-empty
/// directory, so a sibling album staged under the same artist is never touched;
/// any other failure leaves the directory in place and is not an error.
fn prune_empty_dir(dir: &Path) {
    match std::fs::remove_dir(dir) {
        Ok(()) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(e) => tracing::debug!("Artist staging dir {dir:?} left in place: {e}"),
    }
}

