/// True when `path` is, or lies inside, `root`. Both sides are canonicalised, so
/// a symlinked or `.`-containing spelling of either still matches, and a path
/// that does not exist yet is resolved through its deepest existing ancestor
/// instead of failing the comparison.
fn is_inside(root: &Path, path: &Path) -> bool {
    match (canonicalize_lenient(root), canonicalize_lenient(path)) {
        (Some(root), Some(path)) => path == root || path.starts_with(root),
        _ => false,
    }
