/// True when two paths name the same place, existing or not.
pub(crate) fn is_the_same_path(left: &Path, right: &Path) -> bool {
    match (canonicalize_lenient(left), canonicalize_lenient(right)) {
        (Some(left), Some(right)) => left == right,
        _ => false,
    }
