/// Canonicalise a path that may not exist yet by canonicalising its deepest
/// existing ancestor and appending the rest. `fs::canonicalize` requires every
/// component to exist, which is wrong for a path a run is about to create.
fn canonicalize_lenient(path: &Path) -> Option<PathBuf> {
    if let Ok(real) = std::fs::canonicalize(path) {
        return Some(real);
    }
    let mut missing: Vec<std::ffi::OsString> = Vec::new();
    let mut current = path.to_path_buf();
    loop {
        if let Some(name) = current.file_name() {
            missing.push(name.to_os_string());
        }
        let parent = current.parent()?.to_path_buf();
        if let Ok(real) = std::fs::canonicalize(&parent) {
            let mut resolved = real;
            for name in missing.iter().rev() {
                resolved.push(name);
            }
            return Some(resolved);
        }
        current = parent;
    }
}
